262→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
263→  function scopeCustomCss(rawCss, wid) {
264→    if (!rawCss) return "";
265→    // Strip </style> tags to prevent injection
266→    var css = rawCss.replace(/<\/style>/gi, "");
267→    var result = "";
268→    var i = 0;
269→    while (i < css.length) {
270→      // Skip whitespace
271→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
272→      if (i >= css.length) break;
273→      // Pass through @keyframes and @font-face unchanged
274→      if (css[i] === '@') {
275→        var atRule = "";
276→        var j = i;
277→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
278→        var atName = atRule.trim().toLowerCase();
279→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
280→          result += atRule;
281→          if (j < css.length && css[j] === '{') {
282→            var depth = 1; result += css[j]; j++;
283→            while (j < css.length && depth > 0) {
284→              if (css[j] === '{') depth++;
285→              if (css[j] === '}') depth--;
286→              result += css[j]; j++;
287→            }
288→          }
289→          i = j; continue;
290→        }
291→        // @media: scope inner rules
292→        if (atName.indexOf("@media") === 0) {
293→          result += atRule;
294→          if (j < css.length && css[j] === '{') {
295→            result += '{'; j++;
296→            // Collect inner content
297→            var depth = 1; var inner = "";
298→            while (j < css.length && depth > 0) {
299→              if (css[j] === '{') depth++;
300→              if (css[j] === '}') depth--;
301→              if (depth > 0) inner += css[j];
302→              j++;
303→            }
304→            result += scopeCustomCss(inner, wid);
305→            result += '}';
306→          }
307→          i = j; continue;
308→        }
309→      }
310→      // Regular rule: grab selector, prefix with #wid
311→      var sel = ""; var body = "";
312→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
313→      if (i < css.length) { i++; } // skip {
314→      var depth = 1;
315→      while (i < css.length && depth > 0) {
316→        if (css[i] === '{') depth++;
317→        if (css[i] === '}') depth--;
318→        if (depth > 0) body += css[i];
319→        i++;
320→      }
321→      if (sel.trim()) {
322→        // Split multiple selectors by comma and prefix each
323→        var selectors = sel.split(',').map(function(s) {
324→          s = s.trim();
325→          if (!s) return '';
326→          return '#' + wid + ' ' + s;
327→        }).filter(Boolean).join(', ');
328→        result += selectors + ' {' + body + '}';
329→      }
330→    }
331→    return result;
332→  }
